def append_dedup(path, rows):
    with open(path, 'a', encoding='utf-8') as f:
        existing_lines = set(line.strip() for line in f if line.strip())
        for row in rows:
            clean_row = row.strip()
            if clean_row and clean_row not in existing_lines:
                f.write(f'{clean_row}\n')
                existing_lines.add(clean_row)
